#!/bin/bash
# AI DISCLAIMER: All of the text in this file was generated by AI.
# W010: build the FCMP++ prover test binary three times, once per multiexp arm, from one scratch copy of monerodato.9's
# patched monero-oxide (with the W009 harness test added). Only the multiexp source differs between the arms.
#   m051: crates.io multiexp 0.5.1 (before the constant-time Pippenger bucket fix)
#   m052: crates.io multiexp 0.5.2 (with the fix; what stock locks)
#   s4:   monerodato.9's patched multiexp = 0.5.2 + multiexp 0001 (constant-time Straus, 4-bit window, every length)
# usage: build_arms.sh <w010 dir>   Writes <dir>/bins/fcmps-<arm> and <dir>/build.log.
set -u
source ~/.cargo/env
W=$(cd "$1" && pwd); cd "$W/mo"; mkdir -p "$W/bins"; L=$W/build.log; : > "$L"
echo "rustc $(rustc +stable -V); cargo $(cargo +stable -V)" | tee -a "$L"
for arm in m051 m052 s4; do
  C="patch.crates-io.multiexp.path=\"$W/multiexp-${arm#m}\""
  [ $arm = s4 ] && C="patch.crates-io.multiexp.path=\"$W/multiexp-s4\""
  [ $arm = m051 ] && C="patch.crates-io.multiexp.path=\"$W/multiexp-051\""
  [ $arm = m052 ] && C="patch.crates-io.multiexp.path=\"$W/multiexp-052\""
  echo "== arm $arm $(date -u +%FT%TZ) $C" | tee -a "$L"
  CARGO_TARGET_DIR=$W/target nice cargo +stable test --release -j10 -p full-chain-membership-proofs --no-run --config "$C" \
    --message-format=json-render-diagnostics > "$W/build_$arm.json" 2>> "$L" || { echo "BUILD_FAIL $arm" | tee -a "$L"; exit 1; }
  echo "multiexp packages in Cargo.lock: $(grep -c '^name = "multiexp"' Cargo.lock); $(grep -A1 '^name = "multiexp"' Cargo.lock | grep version | paste -sd' ')" | tee -a "$L"
  echo "multiexp source: $(grep -A2 '^name = "multiexp"' Cargo.lock | grep -c source) registry entries (0 = the path)" | tee -a "$L"
  exe=$(python3 -I -c 'import json,sys
for l in open(sys.argv[1]):
    try: m=json.loads(l)
    except Exception: continue
    if m.get("reason")=="compiler-artifact" and m.get("target",{}).get("name")=="full_chain_membership_proofs" and m.get("profile",{}).get("test") and m.get("executable"): print(m["executable"])' "$W/build_$arm.json" | tail -1)
  [ -n "$exe" ] || { echo "NO_EXE $arm" | tee -a "$L"; exit 1; }
  cp "$exe" "$W/bins/fcmps-$arm"; cp Cargo.lock "$W/bins/Cargo.lock.$arm"
  echo "$arm: $(sha256sum "$W/bins/fcmps-$arm" | cut -c1-64) from $exe" | tee -a "$L"
done
echo "BUILD_DONE $(date -u +%FT%TZ)" | tee -a "$L"
